/* eslint-disable @typescript-eslint/no-unused-vars */
import { useMemo, useState } from 'react'
import type { FormEvent } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { geoAlbersUsa, geoMercator, geoPath } from 'd3-geo'
import { feature } from 'topojson-client'
import usStates from 'us-atlas/states-10m.json'
import australiaMap from '@svg-maps/australia'
import japanMap from '@svg-maps/japan'
import southKoreaMap from '@svg-maps/south-korea'
import taiwanMap from '@svg-maps/taiwan'
import ukRegions from './assets/uk-regions.json'
import canadaProvinces from './assets/canada-provinces.json'
import { addTripStop, createTrip, createVisit, deletePlaceStatus, deleteTrip, deleteVisit, exportBackup, getCountries, getHealth, getPlaces, getStatistics, getStatuses, getTrips, getVisits, importBackup, savePlaceStatus, saveStatus, updateTrip, updateVisit, type Country, type Place, type PlaceStatus, type Trip, type Visit } from './api'
import { WorldMap } from './WorldMap'
import './styles.css'

type Page = 'dashboard' | 'countries' | 'regions' | 'places' | 'trips' | 'statistics' | 'settings'
const alphabetical = <T extends { name: string }>(items: T[]) => [...items].sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }))
const nav: { id: Page; label: string; icon: string }[] = [{ id: 'dashboard', label: 'Overview', icon: '⌂' }, { id: 'countries', label: 'Countries', icon: '◎' }, { id: 'regions', label: 'Regions', icon: '▦' }, { id: 'places', label: 'Cities & airports', icon: '⌖' }, { id: 'trips', label: 'Timeline', icon: '↗' }, { id: 'statistics', label: 'Statistics', icon: '◒' }, { id: 'settings', label: 'Settings', icon: '⚙' }]

function App() {
  const [page, setPage] = useState<Page>('dashboard')
  const [addOpen, setAddOpen] = useState(false)
  const [placesType, setPlacesType] = useState<'city' | 'airport'>('city')
  const [regionCountry, setRegionCountry] = useState('US')
  const [selected, setSelected] = useState<Country | null>(null)
  const [query, setQuery] = useState('')
  const client = useQueryClient()
  const countries = useQuery({ queryKey: ['countries'], queryFn: getCountries })
  const regionPlaces = useQuery({ queryKey: ['places', 'region', 'all'], queryFn: () => getPlaces('region') })
  const statuses = useQuery({ queryKey: ['statuses'], queryFn: getStatuses })
  const stats = useQuery({ queryKey: ['statistics'], queryFn: getStatistics })
  const trips = useQuery({ queryKey: ['trips'], queryFn: getTrips })
  const visits = useQuery({ queryKey: ['visits'], queryFn: getVisits })
  const health = useQuery({ queryKey: ['health'], queryFn: getHealth })
  const save = useMutation({ mutationFn: ({ code, status }: { code: string; status: PlaceStatus['status'] }) => saveStatus(code, { status }), onSuccess: () => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }) } })
  const visit = useMutation({ mutationFn: ({ code, arrived_on, departed_on }: { code: string; arrived_on?: string; departed_on?: string }) => createVisit({ place_code: code, arrived_on, departed_on }), onSuccess: () => { client.invalidateQueries({ queryKey: ['statistics'] }); client.invalidateQueries({ queryKey: ['visits'] }) } })
  const removeVisit = useMutation({ mutationFn: (id: string) => deleteVisit(id), onSuccess: () => { client.invalidateQueries({ queryKey: ['statistics'] }); client.invalidateQueries({ queryKey: ['visits'] }) } })
  const editVisit = useMutation({ mutationFn: ({ id, body }: { id: string; body: Omit<Visit, 'id'> }) => updateVisit(id, body), onSuccess: () => { client.invalidateQueries({ queryKey: ['visits'] }); client.invalidateQueries({ queryKey: ['statistics'] }) } })
  const editStatus = useMutation({ mutationFn: async ({ type, oldCode, newCode, body }: { type: string; oldCode: string; newCode: string; body: Pick<PlaceStatus, 'status' | 'first_visited_on' | 'last_visited_on' | 'notes'> }) => { const updated = await savePlaceStatus(type, newCode, body); if (oldCode !== newCode) await deletePlaceStatus(type, oldCode); return updated }, onSuccess: () => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }) } })
  const removeStatus = useMutation({ mutationFn: ({ type, code }: { type: string; code: string }) => deletePlaceStatus(type, code), onSuccess: () => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }); setSelected(null) } })
  const removeTrip = useMutation({ mutationFn: (id: string) => deleteTrip(id), onSuccess: () => { client.invalidateQueries({ queryKey: ['trips'] }); client.invalidateQueries({ queryKey: ['statistics'] }) } })
  const editTrip = useMutation({ mutationFn: ({ id, body }: { id: string; body: Omit<Trip, 'id' | 'stops'> }) => updateTrip(id, body), onSuccess: () => { client.invalidateQueries({ queryKey: ['trips'] }); client.invalidateQueries({ queryKey: ['statistics'] }) } })
  const filteredCountries = useMemo(() => alphabetical((countries.data ?? []).filter((country) => country.name.toLowerCase().includes(query.toLowerCase()) || country.code.toLowerCase() === query.toLowerCase())), [countries.data, query])
  const statusMap = useMemo(() => new Map((statuses.data ?? []).map((item) => [item.place_code, item.status])), [statuses.data])

  const selectCountry = (country: Country) => setSelected(country)
  const setCountryStatus = (status: PlaceStatus['status']) => { if (selected) save.mutate({ code: selected.code, status }) }

  return <div className="app-shell">
    <aside className="sidebar"><div className="brand"><span className="brand-mark">✦</span><span>TravelMap</span></div><p className="sidebar-caption">YOUR WORLD, YOUR STORY</p><nav>{nav.map((item) => <button key={item.id} className={page === item.id ? 'nav-item active' : 'nav-item'} onClick={() => setPage(item.id)}><span>{item.icon}</span>{item.label}</button>)}</nav><div className="sidebar-footer"><span className={`connection ${health.isSuccess ? 'online' : ''}`} /> {health.isSuccess ? 'Local API connected' : 'Waiting for API'}</div></aside>
    <main className="content"><header className="topbar"><div><p className="eyebrow">{page === 'dashboard' ? 'YOUR TRAVEL JOURNAL' : nav.find((item) => item.id === page)?.label.toUpperCase()}</p><h1>{page === 'dashboard' ? 'Welcome back' : nav.find((item) => item.id === page)?.label}</h1></div><div className="top-actions"><button className="add-button" onClick={() => setAddOpen(true)} aria-label="Log a place">+</button></div></header>
      {page === 'dashboard' && <Dashboard stats={stats.data} countries={countries.data ?? []} statuses={statuses.data ?? []} visits={visits.data ?? []} onSelect={selectCountry} />}
      {page === 'countries' && <Countries countries={filteredCountries} statusMap={statusMap} statuses={statuses.data ?? []} onSelect={selectCountry} />}
      {page === 'regions' && <RegionsPage initialCountry={regionCountry} />}
      {page === 'places' && <Places key={placesType} initialType={placesType} />}
      {page === 'trips' && <Timeline countries={countries.data ?? []} regionPlaces={regionPlaces.data ?? []} statuses={statuses.data ?? []} visits={visits.data ?? []} onStatus={(code, status) => save.mutate({ code, status })} onEditStatus={(payload) => editStatus.mutate(payload)} onEditVisit={(id, body) => editVisit.mutate({ id, body })} onDeleteStatus={(type, code) => { if (window.confirm('Delete this timeline status?')) removeStatus.mutate({ type, code }) }} onDeleteVisit={(id) => { if (window.confirm('Delete this visit?')) removeVisit.mutate(id) }} />}
      {page === 'statistics' && <StatisticsPanel stats={stats.data} />}
      {page === 'settings' && <Settings />}
    </main>
    {selected && <CountryPanel country={selected} status={statusMap.get(selected.code)} visits={(visits.data ?? []).filter((item) => item.place_code === selected.code)} onClose={() => setSelected(null)} onStatus={setCountryStatus} onVisit={(arrived_on, departed_on) => visit.mutate({ code: selected.code, arrived_on, departed_on })} onDeleteVisit={(id) => { if (window.confirm('Delete this visit record?')) removeVisit.mutate(id) }} onRemove={() => { if (window.confirm(`Remove your status for ${selected.name}?`)) removeStatus.mutate({ type: 'country', code: selected.code }) }} saving={save.isPending || visit.isPending || removeStatus.isPending || removeVisit.isPending} />}
    {addOpen && <AddMenu onClose={() => setAddOpen(false)} onSelect={(label) => { setAddOpen(false); if (label === 'Countries') setPage('countries'); else if (label === 'Regions') setPage('regions'); else { setPlacesType(label === 'Cities' ? 'city' : 'airport'); setPage('places') } }} />}
  </div>
}

function DashboardLegacy({ stats, countries, statuses, visits, regionPlaces, onSelect, onOpenRegions }: { stats?: import('./api').Statistics; countries: Country[]; statuses: PlaceStatus[]; visits: Visit[]; regionPlaces: Place[]; onSelect: (country: Country) => void; onOpenRegions: (code: string) => void }) {
  const [mapMode, setMapMode] = useState<'country' | 'region'>('country')
  const timelineRecords = new Set([...statuses.map((item) => `${item.place_type}:${item.place_code}`), ...visits.map((item) => `${item.place_type}:${item.place_code}`)]).size
  return <div className="page-stack"><section className="stats-grid"><Metric label="Countries visited" value={stats?.countries_visited ?? 0} suffix={`of ${stats?.recognized_countries ?? 249}`} /><Metric label="World explored" value={`${stats?.visited_percentage ?? 0}%`} /><Metric label="Regions visited" value={`${stats?.regions_percentage ?? 0}%`} suffix={`${stats?.regions_visited ?? 0} of ${stats?.regions_total ?? 0}`} /><Metric label="Timeline records" value={timelineRecords} /></section><section className="map-card"><div className="section-heading"><div><p className="eyebrow">EXPLORE</p><h2>Your world map</h2></div><div className="map-mode"><button className={mapMode === 'country' ? 'filter active' : 'filter'} onClick={() => setMapMode('country')}>Countries</button><button className={mapMode === 'region' ? 'filter active' : 'filter'} onClick={() => setMapMode('region')}>Regions</button></div></div>{mapMode === 'country' ? <><p className="muted map-help">Click any country to update its status.</p><WorldMap countries={countries} statuses={statuses} onSelect={onSelect} /></> : <RegionOverview countries={countries} statuses={statuses} regionPlaces={regionPlaces} onOpenRegions={onOpenRegions} />}</section><section className="split-grid"><div className="panel"><div className="section-heading"><h2>Recent highlights</h2><span className="muted">{statuses.length} marked</span></div>{statuses.length === 0 ? <Empty title="Your map is waiting" body="Start by marking a country on the map." /> : <div className="highlight-list">{statuses.slice(0, 5).map((item) => <div className="highlight" key={item.id}><span className={`status-pill ${item.status}`}>{item.status}</span><strong>{countries.find((country) => country.code === item.place_code)?.name ?? item.place_code}</strong></div>)}</div>}</div><div className="panel quote-panel"><span className="quote-mark">“</span><p>There are no foreign lands. It is only the traveler who is foreign.</p><span className="muted">— Robert Louis Stevenson</span></div></section></div>
}

function RegionOverview({ countries, statuses, regionPlaces, onOpenRegions }: { countries: Country[]; statuses: PlaceStatus[]; regionPlaces: Place[]; onOpenRegions: (code: string) => void }) { const regionStatuses = new Map(statuses.filter((item) => item.place_type === 'region').map((item) => [item.place_code, item.status])); const grouped = new Map<string, Place[]>(); regionPlaces.forEach((place) => { if (place.country_code) grouped.set(place.country_code, [...(grouped.get(place.country_code) ?? []), place]) }); return <div className="region-overview"><p className="muted">Choose a country to open its own regional map and independent progress.</p><div className="country-grid">{alphabetical(countries.filter((country) => grouped.has(country.code))).map((country) => { const items = alphabetical(grouped.get(country.code) ?? []); const visited = items.filter((item) => regionStatuses.get(item.code) === 'visited').length; return <button className="country-card region-country-card" key={country.code} onClick={() => onOpenRegions(country.code)}><span className="country-code">{country.code}</span><strong>{country.name}</strong><span className="region-percent">{visited} of {items.length} regions · {items.length ? Math.round(visited / items.length * 100) : 0}%</span><span className="status-pill visited">Open regional map</span></button> })}</div></div> }

function Countries({ countries, statusMap, statuses, onSelect }: { countries: Country[]; statusMap: Map<string, PlaceStatus['status']>; statuses: PlaceStatus[]; onSelect: (country: Country) => void }) {
  const [filter, setFilter] = useState<'all' | 'visited' | 'lived'>('all')
  const visible = countries.filter((country) => filter === 'all' || statusMap.get(country.code) === filter)
  return <div className="page-stack"><section className="map-card"><div className="section-heading"><div><p className="eyebrow">EXPLORE</p><h2>World map</h2></div></div><WorldMap countries={countries} statuses={statuses} onSelect={onSelect} /></section><div className="toolbar"><span className="muted">{visible.length} countries</span><div className="filter-row"><button className={`filter ${filter === 'all' ? 'active' : ''}`} onClick={() => setFilter('all')}>All</button><button className={`filter ${filter === 'visited' ? 'active' : ''}`} onClick={() => setFilter('visited')}>Visited</button><button className={`filter ${filter === 'lived' ? 'active' : ''}`} onClick={() => setFilter('lived')}>Lived</button></div></div><div className="country-grid">{visible.map((country) => <button className="country-card" key={country.code} onClick={() => onSelect(country)}><span className="country-code">{country.code}</span><strong>{country.name}</strong><span className={`status-pill ${statusMap.get(country.code) ?? 'unmarked'}`}>{statusMap.get(country.code) ?? 'unmarked'}</span></button>)}</div></div>
}

function RegionsPage({ initialCountry }: { initialCountry: string }) { const [country, setCountry] = useState(initialCountry); const [selected, setSelected] = useState<Place | null>(null); const countries = useQuery({ queryKey: ['countries'], queryFn: getCountries }); const places = useQuery({ queryKey: ['places', 'region', country], queryFn: () => getPlaces('region', country) }); const statuses = useQuery({ queryKey: ['statuses'], queryFn: getStatuses }); const client = useQueryClient(); const regionStatuses = new Map((statuses.data ?? []).filter((item) => item.place_type === 'region').map((item) => [item.place_code, item])); const visited = (places.data ?? []).filter((place) => regionStatuses.get(place.code)?.status === 'visited').length; const selectedStatus = selected ? regionStatuses.get(selected.code) : undefined; const setStatus = (status: PlaceStatus['status']) => { if (!selected) return; savePlaceStatus('region', selected.code, { status }).then(() => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }) }) }; const remove = () => { if (selected && window.confirm(`Remove your status for ${selected.name}?`)) deletePlaceStatus('region', selected.code).then(() => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }); setSelected(null) }) }; const logged = new Set([...regionStatuses].filter(([, item]) => item.status === 'visited').map(([code]) => code)); const mapData = countryRegionMaps[country]; const hasInteractiveMap = country === 'US' || Boolean(mapData); return <div className="page-stack"><section className="panel region-header"><div><p className="eyebrow">REGIONAL EXPLORATION</p><h2>Regions by country</h2><p className="muted">Each country has its own map and percentage. Regions are never combined across countries here.</p></div><select className="country-filter" value={country} onChange={(event) => { setCountry(event.target.value); setSelected(null) }}>{alphabetical(countries.data ?? []).map((item) => <option key={item.code} value={item.code}>{item.name}</option>)}</select></section><section className="panel region-detail"><div className="section-heading"><div><p className="eyebrow">{countries.data?.find((item) => item.code === country)?.name ?? country}</p><h2>{visited} of {places.data?.length ?? 0} regions visited</h2></div><strong className="region-big-percent">{places.data?.length ? Math.round(visited / places.data.length * 100) : 0}%</strong></div>{country === 'US' ? <USStateMap places={places.data ?? []} statuses={regionStatuses} onSelect={setSelected} /> : mapData ? <SvgRegionMap mapData={mapData} places={places.data ?? []} statuses={regionStatuses} onSelect={setSelected} /> : <RegionMiniMap places={places.data ?? []} logged={logged} onSelect={setSelected} />}{hasInteractiveMap && <div className="country-grid region-list">{alphabetical(places.data ?? []).map((place) => { const status = regionStatuses.get(place.code); return <button className="country-card place-select-card" key={place.code} onClick={() => setSelected(place)}><span className="country-code">{place.code}</span><strong>{place.name}</strong><span className={`status-pill ${status?.status ?? 'unmarked'}`}>{status?.status ?? 'unmarked'}</span></button> })}</div>}</section>{selected && <PlacePanel place={selected} status={selectedStatus} onClose={() => setSelected(null)} onStatus={setStatus} onRemove={remove} />}</div> }

function Places({ initialType = 'city' }: { initialType?: 'city' | 'airport' }) {
  const [type, setType] = useState<'city' | 'airport'>(initialType)
  const [country, setCountry] = useState('US')
  const [expanded, setExpanded] = useState(false)
  const [selected, setSelected] = useState<Place | null>(null)
  const places = useQuery({ queryKey: ['places', type, country, expanded], queryFn: () => getPlaces(type, country, type !== 'city' || !expanded) })
  const statuses = useQuery({ queryKey: ['statuses'], queryFn: getStatuses })
  const client = useQueryClient()
  const remove = useMutation({ mutationFn: ({ placeType, code }: { placeType: string; code: string }) => deletePlaceStatus(placeType, code), onSuccess: () => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }); setSelected(null) } })
  const logged = new Set((statuses.data ?? []).filter((item) => item.place_type === type && item.status === 'visited').map((item) => item.place_code))
  const grouped = new Map<string, Place[]>()
  alphabetical((places.data ?? []).filter((place) => place.name.trim())).forEach((place) => { const key = place.country_code ?? 'Other'; grouped.set(key, [...(grouped.get(key) ?? []), place]) })
  const allCountries = useQuery({ queryKey: ['countries'], queryFn: getCountries })
  const selectedStatus = selected ? statuses.data?.find((item) => item.place_type === selected.place_type && item.place_code === selected.code) : undefined
  return <div className="page-stack"><div className="toolbar"><span className="muted">{places.data?.filter((place) => place.name.trim()).length ?? 0} {type === 'city' ? 'cities' : 'airports'} in {countriesName(country)}</span><div className="filter-row"><select className="country-filter" value={country} onChange={(event) => { setCountry(event.target.value); setSelected(null) }}>{alphabetical(allCountries.data ?? []).map((item) => <option key={item.code} value={item.code}>{item.name}</option>)}</select>{(['city', 'airport'] as const).map((item) => <button key={item} className={`filter ${type === item ? 'active' : ''}`} onClick={() => { setType(item); setExpanded(false); setSelected(null) }}>{item === 'city' ? 'Cities' : 'Airports'}</button>)}{type === 'city' && <button className="filter" onClick={() => setExpanded(!expanded)}>{expanded ? 'Show featured cities' : 'Show more cities'}</button>}</div></div><div className="group-list">{Array.from(grouped.entries()).sort((a, b) => countriesName(a[0]).localeCompare(countriesName(b[0]), undefined, { sensitivity: 'base' })).map(([countryCode, items]) => <section className="place-group" key={countryCode}><div className="section-heading"><h2>{countriesName(countryCode)}</h2><span className="muted">{items.length}</span></div><div className="place-list">{items.map((place) => <button className={`place-list-row ${logged.has(place.code) ? 'logged' : ''}`} key={place.code} onClick={() => setSelected(place)}><strong>{place.name}</strong><span className="place-list-type">{type === 'city' ? 'City' : 'Airport'}</span><span className={`status-pill ${selectedStatus?.place_code === place.code ? selectedStatus.status : logged.has(place.code) ? 'visited' : 'unmarked'}`}>{logged.has(place.code) ? 'Visited' : 'Not visited'}</span></button>)}</div></section>)}</div>{selected && <PlacePanel place={selected} status={selectedStatus} onClose={() => setSelected(null)} onStatus={(status, first, last) => savePlaceStatus(selected.place_type, selected.code, { status, first_visited_on: first || undefined, last_visited_on: last || undefined }).then(() => { client.invalidateQueries({ queryKey: ['statuses'] }); client.invalidateQueries({ queryKey: ['statistics'] }) })} onRemove={() => { if (window.confirm(`Remove your status for ${selected.name}?`)) remove.mutate({ placeType: selected.place_type, code: selected.code }) }} />}</div>
}

function PlacePanel({ place, status, onClose, onStatus, onRemove }: { place: Place; status?: PlaceStatus; onClose: () => void; onStatus: (status: PlaceStatus['status'], visitedOn?: string, unused?: string) => void; onRemove: () => void }) { const [visitedOn, setVisitedOn] = useState(status?.first_visited_on ?? status?.last_visited_on ?? ''); return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><button className="close" onClick={onClose}>×</button><span className="country-code big">{place.place_type.toUpperCase()}</span><h2>{place.name}</h2><p className="muted">{status ? `Marked as ${status.status}.` : 'Not marked yet.'}</p><p className="eyebrow">SET STATUS</p><div className="status-actions">{(['visited', 'lived', 'planned'] as const).map((value) => <button key={value} className={`status-choice ${status?.status === value ? 'selected' : ''} ${value}`} onClick={() => onStatus(value, visitedOn)}>{value}</button>)}</div><div className="date-fields place-dates"><label>Visited date<input type="date" value={visitedOn} onChange={(event) => setVisitedOn(event.target.value)} /></label></div>{status && <button className="danger-link drawer-delete" onClick={onRemove}>Remove status record</button>}<p className="muted small">Each visit is stored separately, so returning to the same place is fully supported.</p></aside></div> }
function USStateMap({ places, statuses, onSelect }: { places: Place[]; statuses: Map<string, PlaceStatus>; onSelect: (place: Place) => void }) { const collection = useMemo(() => feature(usStates as never, usStates.objects.states as never) as unknown as GeoJSON.FeatureCollection, []); const projection = useMemo(() => geoAlbersUsa().fitSize([900, 500], collection), [collection]); const path = useMemo(() => geoPath(projection), [projection]); const byName = new Map(places.map((place) => [place.name.toLowerCase(), place])); return <div className="us-map"><svg viewBox="0 0 900 500" role="img" aria-label="Interactive United States regions map"><rect width="900" height="500" rx="20" fill="#0b2a37" />{collection.features.map((shape) => { const name = String((shape.properties as { name?: string } | null)?.name ?? ''); const place = byName.get(name.toLowerCase()); if (!place) return null; const status = statuses.get(place.code)?.status; return <path key={place.code} d={path(shape) ?? ''} className={`state-shape ${status ?? ''}`} onClick={() => onSelect(place)} tabIndex={0} role="button" aria-label={place.name} onKeyDown={(event) => { if (event.key === 'Enter') onSelect(place) }} /> })}</svg><div className="map-legend"><span><i className="legend-swatch visited" /> Visited</span><span><i className="legend-swatch lived" /> Lived</span><span><i className="legend-swatch planned" /> Planned</span></div></div> }
function UKRegionMap({ places, statuses, onSelect }: { places: Place[]; statuses: Map<string, PlaceStatus>; onSelect: (place: Place) => void }) { const collection = useMemo(() => feature(ukRegions as never, ukRegions.objects.UKregionmerc as never) as unknown as GeoJSON.FeatureCollection, []); const projection = useMemo(() => geoMercator().fitSize([900, 500], collection), [collection]); const path = useMemo(() => geoPath(projection), [projection]); const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, ''); const findPlace = (name: string) => places.find((place) => { const a = normalize(place.name); const b = normalize(name); return a === b || a.includes(b) || b.includes(a) }); return <div className="uk-map"><svg viewBox="0 0 900 500" role="img" aria-label="Interactive United Kingdom regional map"><rect width="900" height="500" rx="20" fill="#0b2a37" />{collection.features.map((shape, index) => { const name = String((shape.properties as { AREANM?: string } | null)?.AREANM ?? ''); const place = findPlace(name); const status = place ? statuses.get(place.code)?.status : undefined; return <path key={`${name}-${index}`} d={path(shape) ?? ''} className={`uk-region-shape ${status ?? ''}`} onClick={() => place && onSelect(place)} tabIndex={place ? 0 : -1} role={place ? 'button' : undefined} aria-label={name} onKeyDown={(event) => { if (place && event.key === 'Enter') onSelect(place) }}><title>{name}</title></path> })}</svg><div className="map-legend"><span><i className="legend-swatch visited" /> Visited</span><span><i className="legend-swatch lived" /> Lived</span></div><span className="muted small">Select a region boundary to update its status.</span></div> }
function CanadaRegionMap({ places, statuses, onSelect }: { places: Place[]; statuses: Map<string, PlaceStatus>; onSelect: (place: Place) => void }) { const collection = canadaProvinces as unknown as GeoJSON.FeatureCollection; const projection = useMemo(() => geoMercator().fitSize([900, 500], collection), [collection]); const path = useMemo(() => geoPath(projection), [projection]); const findPlace = (name: string) => places.find((place) => place.name.toLowerCase() === name.toLowerCase()); return <div className="us-map"><svg viewBox="0 0 900 500" role="img" aria-label="Interactive Canada provinces and territories map"><rect width="900" height="500" rx="20" fill="#0b2a37" />{collection.features.map((shape, index) => { const name = String((shape.properties as { name?: string } | null)?.name ?? ''); const place = findPlace(name); const current = place ? statuses.get(place.code)?.status : undefined; return <path key={`${name}-${index}`} d={path(shape) ?? ''} className={`state-shape ${current ?? ''}`} onClick={() => place && onSelect(place)} tabIndex={place ? 0 : -1} role={place ? 'button' : undefined} aria-label={name}><title>{name}</title></path> })}</svg><div className="map-legend"><span><i className="legend-swatch visited" /> Visited</span><span><i className="legend-swatch lived" /> Lived</span></div></div> }
type SvgRegionMapData = { label: string; viewBox: string; locations: { id: string; name: string; path: string }[] }
const ukMapData: SvgRegionMapData = { label: 'Interactive United Kingdom regions map', viewBox: '0 0 900 500', locations: [] }
const canadaMapData: SvgRegionMapData = { label: 'Interactive Canada provinces and territories map', viewBox: '0 0 900 500', locations: [] }
const countryRegionMaps: Record<string, SvgRegionMapData> = { CA: canadaMapData, GB: ukMapData, TW: taiwanMap, JP: japanMap, KR: southKoreaMap, AU: australiaMap }
function SvgRegionMap({ mapData, places, statuses, onSelect }: { mapData: SvgRegionMapData; places: Place[]; statuses: Map<string, PlaceStatus>; onSelect: (place: Place) => void }) { if (mapData === ukMapData) return <UKRegionMap places={places} statuses={statuses} onSelect={onSelect} />; if (mapData === canadaMapData) return <CanadaRegionMap places={places} statuses={statuses} onSelect={onSelect} />; const normalize = (value: string) => value.toLowerCase().replace(/[^a-z0-9]/g, ''); const findPlace = (name: string) => places.find((place) => { const a = normalize(place.name); const b = normalize(name); return a === b || a.includes(b) || b.includes(a) }); return <div className="svg-region-map"><svg viewBox={mapData.viewBox} role="img" aria-label={mapData.label}>{mapData.locations.map((location) => { const place = findPlace(location.name); const status = place ? statuses.get(place.code)?.status : undefined; return <path key={location.id} d={location.path} className={`svg-region-shape ${status ?? ''}`} onClick={() => place && onSelect(place)} tabIndex={place ? 0 : -1} role={place ? 'button' : undefined} aria-label={location.name} onKeyDown={(event) => { if (place && event.key === 'Enter') onSelect(place) }} /> })}</svg><div className="map-legend"><span><i className="legend-swatch visited" /> Visited</span><span><i className="legend-swatch lived" /> Lived</span><span><i className="legend-swatch planned" /> Planned</span></div></div> }
function RegionMiniMap({ places, logged, onSelect }: { places: Place[]; logged: Set<string>; onSelect: (place: Place) => void }) { const points = places.filter((place) => place.latitude != null && place.longitude != null); if (!points.length) return <RegionGridMap places={places} logged={logged} onSelect={onSelect} />; const lats = points.map((place) => place.latitude as number); const lons = points.map((place) => place.longitude as number); const minLat = Math.min(...lats); const maxLat = Math.max(...lats); const minLon = Math.min(...lons); const maxLon = Math.max(...lons); const x = (lon: number) => 24 + ((lon - minLon) / (maxLon - minLon || 1)) * 552; const y = (lat: number) => 206 - ((lat - minLat) / (maxLat - minLat || 1)) * 176; return <div className="mini-map"><svg viewBox="0 0 600 230" role="img" aria-label="Regional map"><rect width="600" height="230" rx="16" fill="#0d3440" />{Array.from({ length: 6 }, (_, index) => <line key={`v-${index}`} x1={24 + index * 110} x2={24 + index * 110} y1="18" y2="212" stroke="#174b57" />)}{Array.from({ length: 4 }, (_, index) => <line key={`h-${index}`} x1="18" x2="582" y1={32 + index * 58} y2={32 + index * 58} stroke="#174b57" />)}{points.map((place) => <circle key={place.code} cx={x(place.longitude as number)} cy={y(place.latitude as number)} r={logged.has(place.code) ? 8 : 6} fill={logged.has(place.code) ? '#6fd5c4' : '#4d7f89'} stroke="#092630" strokeWidth="2" onClick={() => onSelect(place)} role="button" aria-label={place.name} />)}</svg><span className="muted small">Click a region marker to update its status.</span></div> }
function RegionGridMap({ places, logged, onSelect }: { places: Place[]; logged: Set<string>; onSelect: (place: Place) => void }) { return <div className="region-grid-map" role="group" aria-label="Interactive regional map">{places.map((place) => <button key={place.code} className={logged.has(place.code) ? 'region-grid-cell visited' : 'region-grid-cell'} onClick={() => onSelect(place)}><span>{place.name}</span><small>{logged.has(place.code) ? 'Visited' : 'Not visited'}</small></button>)}</div> }
function AddMenu({ onClose, onSelect }: { onClose: () => void; onSelect: (label: string) => void }) { return <div className="add-backdrop" onClick={onClose}><div className="add-menu" onClick={(event) => event.stopPropagation()}><h2>Log a place</h2><p className="muted">Choose what you want to track.</p>{['Countries', 'Regions', 'Cities', 'Airports'].map((label) => <button key={label} onClick={() => onSelect(label)}><span>＋</span>{label}</button>)}</div></div> }
function countriesName(code: string) { return code === 'Other' ? code : new Intl.DisplayNames(['en'], { type: 'region' }).of(code) ?? code }

function Timeline({ countries, regionPlaces, statuses, visits, onStatus, onEditStatus, onEditVisit, onDeleteStatus, onDeleteVisit }: { countries: Country[]; regionPlaces: Place[]; statuses: PlaceStatus[]; visits: Visit[]; onStatus: (code: string, status: PlaceStatus['status']) => void; onEditStatus: (payload: { type: string; oldCode: string; newCode: string; body: Pick<PlaceStatus, 'status' | 'first_visited_on' | 'last_visited_on' | 'notes'> }) => void; onEditVisit: (id: string, body: Omit<Visit, 'id'>) => void; onDeleteStatus: (type: string, code: string) => void; onDeleteVisit: (id: string) => void }) {
  const cityPlaces = useQuery({ queryKey: ['places', 'city', 'timeline'], queryFn: () => getPlaces('city') }).data ?? []
  const airportPlaces = useQuery({ queryKey: ['places', 'airport', 'timeline'], queryFn: () => getPlaces('airport') }).data ?? []
  const countryName = (code: string) => countries.find((country) => country.code === code)?.name ?? regionPlaces.find((place) => place.code === code)?.name ?? code
  const placeDetails = (item: { place_type: string; place_code: string }) => {
    if (item.place_type === 'country') return { name: countryName(item.place_code), parent: '' }
    const source = item.place_type === 'region' ? regionPlaces : item.place_type === 'city' ? cityPlaces : airportPlaces
    const place = source.find((candidate) => candidate.code === item.place_code)
    return { name: place?.name ?? item.place_code, parent: place?.country_code ? countryName(place.country_code) : '' }
  }
  const placesWithVisits = new Set(visits.map((item) => item.place_code))
  const entries = [...statuses.filter((item) => !placesWithVisits.has(item.place_code)).map((item) => ({ kind: 'status' as const, date: item.last_visited_on ?? item.first_visited_on ?? '', item })), ...visits.map((item) => ({ kind: 'visit' as const, date: item.arrived_on ?? '', item }))].sort((a, b) => b.date.localeCompare(a.date))
  return <div className="page-stack"><section className="panel"><p className="eyebrow">YOUR TRAVEL HISTORY</p><h2>Timeline</h2><p className="muted">Changes made from Overview appear here automatically. Edit the status, dates, or place for any record.</p></section><div className="timeline">{entries.length === 0 ? <Empty title="Your timeline is empty" body="Mark a country or log a visit from Overview to begin." /> : entries.map((entry) => { const details = placeDetails(entry.item); return <article className="timeline-item" key={`${entry.kind}-${entry.item.id}`}><span className="timeline-dot" /><div className="timeline-event"><div>{!(entry.kind === 'status' && entry.item.place_type === 'city') && <span className="eyebrow">{entry.kind === 'status' ? `${entry.item.place_type.toUpperCase()} STATUS` : 'VISIT'}</span>}<h2>{details.name}</h2>{details.parent && <p className="muted">{details.parent}</p>}<p className="muted">{entry.date || 'Date not set'}</p></div>{entry.kind === 'status' ? <div className="timeline-controls"><select value={entry.item.status} onChange={(event) => onStatus(entry.item.place_code, event.target.value as PlaceStatus['status'])}><option value="visited">Visited</option><option value="lived">Lived</option><option value="planned">Planned</option></select><TimelineStatusEditor item={entry.item} countries={countries} regionPlaces={regionPlaces} cityPlaces={cityPlaces} airportPlaces={airportPlaces} onSave={onEditStatus} /><button className="danger-link" onClick={() => onDeleteStatus(entry.item.place_type, entry.item.place_code)}>Delete</button></div> : <div className="timeline-controls"><TimelineVisitEditor item={entry.item} countries={countries} regionPlaces={regionPlaces} cityPlaces={cityPlaces} airportPlaces={airportPlaces} onSave={onEditVisit} /><button className="danger-link" onClick={() => onDeleteVisit(entry.item.id)}>Delete visit</button></div>}</div></article> })}</div></div>
}

function TimelineStatusEditor({ item, countries, regionPlaces, cityPlaces, airportPlaces, onSave }: { item: PlaceStatus; countries: Country[]; regionPlaces: Place[]; cityPlaces: Place[]; airportPlaces: Place[]; onSave: (payload: { type: string; oldCode: string; newCode: string; body: Pick<PlaceStatus, 'status' | 'first_visited_on' | 'last_visited_on' | 'notes'> }) => void }) { const [editing, setEditing] = useState(false); const [code, setCode] = useState(item.place_code); const [first, setFirst] = useState(item.first_visited_on ?? ''); const [last, setLast] = useState(item.last_visited_on ?? ''); const options = item.place_type === 'country' ? countries.map((place) => ({ code: place.code, name: place.name })) : (item.place_type === 'region' ? regionPlaces : item.place_type === 'city' ? cityPlaces : airportPlaces).map((place) => ({ code: place.code, name: place.name })); if (!editing) return <button className="filter" onClick={() => setEditing(true)}>Edit</button>; return <form className="timeline-editor" onSubmit={(event) => { event.preventDefault(); onSave({ type: item.place_type, oldCode: item.place_code, newCode: code, body: { status: item.status, first_visited_on: first || undefined, last_visited_on: last || undefined } }); setEditing(false) }}><select value={code} onChange={(event) => setCode(event.target.value)}>{options.map((option) => <option key={option.code} value={option.code}>{option.name}</option>)}</select><input type="date" value={first} onChange={(event) => setFirst(event.target.value)} aria-label="First visited date" /><input type="date" value={last} onChange={(event) => setLast(event.target.value)} aria-label="Last visited date" /><button className="primary" type="submit">Save</button><button className="filter" type="button" onClick={() => setEditing(false)}>Cancel</button></form> }
function TimelineVisitEditor({ item, countries, regionPlaces, cityPlaces, airportPlaces, onSave }: { item: Visit; countries: Country[]; regionPlaces: Place[]; cityPlaces: Place[]; airportPlaces: Place[]; onSave: (id: string, body: Omit<Visit, 'id'>) => void }) { const [editing, setEditing] = useState(false); const [code, setCode] = useState(item.place_code); const [type, setType] = useState(item.place_type); const [arrived, setArrived] = useState(item.arrived_on ?? ''); const [departed, setDeparted] = useState(item.departed_on ?? ''); const options = type === 'country' ? countries.map((place) => ({ code: place.code, name: place.name })) : (type === 'region' ? regionPlaces : type === 'city' ? cityPlaces : airportPlaces).map((place) => ({ code: place.code, name: place.name })); if (!editing) return <button className="filter" onClick={() => setEditing(true)}>Edit</button>; return <form className="timeline-editor" onSubmit={(event) => { event.preventDefault(); onSave(item.id, { place_type: type, place_code: code, arrived_on: arrived || undefined, departed_on: departed || undefined, trip_id: item.trip_id, notes: item.notes }); setEditing(false) }}><select value={type} onChange={(event) => { const next = event.target.value as Visit['place_type']; setType(next); setCode(next === 'country' ? countries[0]?.code ?? '' : next === 'region' ? regionPlaces[0]?.code ?? '' : next === 'city' ? cityPlaces[0]?.code ?? '' : airportPlaces[0]?.code ?? '') }}><option value="country">Country</option><option value="region">Region</option><option value="city">City</option><option value="airport">Airport</option></select><select value={code} onChange={(event) => setCode(event.target.value)}>{options.map((option) => <option key={option.code} value={option.code}>{option.name}</option>)}</select><input type="date" value={arrived} onChange={(event) => setArrived(event.target.value)} aria-label="Arrived date" /><input type="date" value={departed} onChange={(event) => setDeparted(event.target.value)} aria-label="Departed date" /><button className="primary" type="submit">Save</button><button className="filter" type="button" onClick={() => setEditing(false)}>Cancel</button></form> }

function Trips({ trips, countries, onCreated, onDelete, onEdit }: { trips: Trip[]; countries: Country[]; onCreated: () => void; onDelete: (id: string) => void; onEdit: (id: string, body: Omit<Trip, 'id' | 'stops'>) => void }) {
  const [name, setName] = useState(''); const [countryCode, setCountryCode] = useState('')
  const create = useMutation({ mutationFn: async () => { const tripName = name.trim() || (countryCode ? `Trip to ${countries.find((country) => country.code === countryCode)?.name ?? countryCode}` : ''); if (!tripName) throw new Error('Enter a trip name or choose a country.'); const trip = await createTrip({ name: tripName, status: 'planned' }); if (countryCode) await addTripStop(trip.id, { place_code: countryCode, position: 0 }); return trip }, onSuccess: () => { setName(''); setCountryCode(''); onCreated() } })
  const submit = (event: FormEvent) => { event.preventDefault(); create.mutate() }
  const ordered = [...trips].sort((a, b) => (a.start_date ?? '9999').localeCompare(b.start_date ?? '9999'))
  return <div className="page-stack"><section className="panel create-panel"><div><p className="eyebrow">NEW ADVENTURE</p><h2>Add to your timeline</h2></div><form onSubmit={submit}><input value={name} onChange={(event) => setName(event.target.value)} placeholder="Trip name, e.g. Summer in Japan" /><select value={countryCode} onChange={(event) => setCountryCode(event.target.value)} aria-label="Trip country"><option value="">Add a country…</option>{countries.map((country) => <option value={country.code} key={country.code}>{country.name}</option>)}</select><button className="primary" disabled={create.isPending}>Create trip</button></form>{create.isError && <p className="form-error">{create.error instanceof Error ? create.error.message : 'Could not create the trip.'}</p>}</section><div className="timeline">{ordered.length === 0 ? <Empty title="Your timeline is empty" body="Create a trip above to start building your travel history." /> : ordered.map((trip) => <TimelineTrip key={trip.id} trip={trip} countries={countries} onDelete={onDelete} onEdit={onEdit} />)}</div></div>
}

function TimelineTrip({ trip, countries, onDelete, onEdit }: { trip: Trip; countries: Country[]; onDelete: (id: string) => void; onEdit: (id: string, body: Omit<Trip, 'id' | 'stops'>) => void }) { const [editing, setEditing] = useState(false); const [name, setName] = useState(trip.name); const [start, setStart] = useState(trip.start_date ?? ''); const [end, setEnd] = useState(trip.end_date ?? ''); const [status, setStatus] = useState(trip.status); const [notes, setNotes] = useState(trip.notes ?? ''); return <article className="timeline-item"><span className="timeline-dot" /><div className="trip-card"><div className="trip-icon">✈</div><div className="trip-content">{editing ? <form className="trip-edit" onSubmit={(event) => { event.preventDefault(); onEdit(trip.id, { name, start_date: start || undefined, end_date: end || undefined, status, notes: notes || undefined }); setEditing(false) }}><input value={name} onChange={(event) => setName(event.target.value)} aria-label="Trip name" /><div className="date-fields"><label>Start<input type="date" value={start} onChange={(event) => setStart(event.target.value)} /></label><label>End<input type="date" value={end} onChange={(event) => setEnd(event.target.value)} /></label></div><select value={status} onChange={(event) => setStatus(event.target.value as Trip['status'])}><option value="planned">Planned</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><textarea value={notes} onChange={(event) => setNotes(event.target.value)} placeholder="Notes" /><div><button className="primary" type="submit">Save changes</button><button className="filter" type="button" onClick={() => setEditing(false)}>Cancel</button></div></form> : <><div className="trip-heading"><div><h2>{trip.name}</h2><span className={`status-pill ${trip.status}`}>{trip.status}</span></div><div><button className="filter" onClick={() => setEditing(true)}>Edit</button><button className="danger-link" onClick={() => onDelete(trip.id)}>Delete</button></div></div><p className="muted">{trip.start_date || 'Date not set'}{trip.end_date ? ` → ${trip.end_date}` : ''} · {trip.stops.length} stop{trip.stops.length === 1 ? '' : 's'}</p><p className="muted">{trip.notes || 'No notes yet'}</p><div className="stop-row">{trip.stops.map((stop) => <span key={stop.id}>{countries.find((country) => country.code === stop.place_code)?.name ?? stop.place_code}</span>)}</div></>}</div></div></article> }

function StatisticsPanel({ stats }: { stats?: import('./api').Statistics }) {
  return <div className="page-stack"><section className="stats-grid large"><Metric label="Countries visited" value={stats?.countries_visited ?? 0} /><Metric label="Regions visited" value={stats?.regions_visited ?? 0} /><Metric label="Cities visited" value={stats?.cities_visited ?? 0} /><Metric label="Airports visited" value={stats?.airports_visited ?? 0} /></section><section className="panel chart-panel"><div className="section-heading"><div><p className="eyebrow">PROGRESS</p><h2>World exploration</h2></div><strong>{stats?.visited_percentage ?? 0}%</strong></div><div className="progress"><span style={{ width: `${stats?.visited_percentage ?? 0}%` }} /></div><p className="muted">Based on {stats?.recognized_countries ?? 249} recognized countries. Planned places are not counted as visited.</p><div className="stats-summary"><span>{stats?.countries_lived ?? 0} lived in</span><span>{stats?.countries_planned ?? 0} planned</span><span>{stats?.visits ?? 0} visit records</span></div></section></div>
}

function Settings() { const [message, setMessage] = useState(''); const downloadBackup = async () => { const payload = await exportBackup(); const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `travelmap-backup-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url) }; return <div className="page-stack"><section className="panel settings-panel"><p className="eyebrow">LOCAL DATA</p><h2>Your data stays on this laptop</h2><p className="muted">TravelMap stores your places and trips in the local SQLite database. Export a portable JSON backup whenever you like.</p><div className="settings-actions"><button className="primary" onClick={downloadBackup}>Export backup</button><label className="secondary-button">Import backup<input type="file" accept="application/json" onChange={async (event) => { const file = event.target.files?.[0]; if (!file) return; try { const result = await importBackup(JSON.parse(await file.text()) as Record<string, unknown>); setMessage(`Restored ${result.statuses} statuses and ${result.trips} trips.`) } catch (error) { setMessage(error instanceof Error ? error.message : 'Import failed') } }} /></label></div>{message && <p className="muted">{message}</p>}</section><section className="panel"><p className="eyebrow">ABOUT</p><h2>TravelMap</h2><p className="muted">An original, local-first travel journal inspired by the joy of keeping track of places—not a copy of any proprietary app.</p></section></div> }

function CountryPanel({ country, status, visits, onClose, onStatus, onVisit, onDeleteVisit, onRemove, saving }: { country: Country; status?: PlaceStatus['status']; visits: Visit[]; onClose: () => void; onStatus: (status: PlaceStatus['status']) => void; onVisit: (arrived_on?: string, departed_on?: string) => void; onDeleteVisit: (id: string) => void; onRemove: () => void; saving: boolean }) { const [arrived, setArrived] = useState(''); const [departed, setDeparted] = useState(''); return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer" onClick={(event) => event.stopPropagation()}><button className="close" onClick={onClose}>×</button><span className="country-code big">{country.code}</span><h2>{country.name}</h2><p className="muted">{status ? `Marked as ${status}.` : 'Not marked yet.'}</p><p className="eyebrow">SET STATUS</p><div className="status-actions">{(['visited', 'lived', 'planned'] as const).map((value) => <button key={value} className={`status-choice ${status === value ? 'selected' : ''} ${value}`} onClick={() => onStatus(value)} disabled={saving}>{value}</button>)}</div><p className="eyebrow visit-heading">ADD VISIT DATES</p><div className="date-fields"><label>Arrived<input type="date" value={arrived} onChange={(event) => setArrived(event.target.value)} /></label><label>Departed<input type="date" value={departed} onChange={(event) => setDeparted(event.target.value)} /></label></div><button className="primary visit-button" onClick={() => onVisit(arrived || undefined, departed || undefined)} disabled={saving}>Log another visit</button>{visits.length > 0 && <div className="visit-history"><p className="eyebrow">VISIT HISTORY ({visits.length})</p>{visits.map((item) => <div className="visit-row" key={item.id}><span>{item.arrived_on || 'Date not set'}{item.departed_on ? ` → ${item.departed_on}` : ''}</span><button className="danger-link" onClick={() => onDeleteVisit(item.id)}>Delete</button></div>)}</div>}{status && <button className="danger-link drawer-delete" onClick={onRemove} disabled={saving}>Remove status record</button>}<p className="muted small">Each visit is stored separately, so returning to the same place is fully supported.</p></aside></div> }
function Metric({ label, value, suffix }: { label: string; value: string | number; suffix?: string }) { return <div className="metric"><span className="muted">{label}</span><strong>{value}</strong>{suffix && <small>{suffix}</small>}</div> }
function Empty({ title, body }: { title: string; body: string }) { return <div className="empty"><strong>{title}</strong><span className="muted">{body}</span></div> }

function Dashboard({ stats, countries, statuses, visits, onSelect }: { stats?: import('./api').Statistics; countries: Country[]; statuses: PlaceStatus[]; visits: Visit[]; onSelect: (country: Country) => void }) { const names: Record<string, string> = { AF: 'Africa', AS: 'Asia', EU: 'Europe', NA: 'North America', OC: 'Oceania', SA: 'South America' }; const continents = Object.entries(names).map(([code, name]) => { const members = countries.filter((country) => country.continent === code); const visited = members.filter((country) => ['visited', 'lived'].includes(statuses.find((item) => item.place_type === 'country' && item.place_code === country.code)?.status ?? '')).length; return { name, visited, total: members.length } }); const records = new Set([...statuses.map((item) => `${item.place_type}:${item.place_code}`), ...visits.map((item) => `${item.place_type}:${item.place_code}`)]).size; return <div className="page-stack"><section className="stats-grid"><Metric label="Countries visited" value={stats?.countries_visited ?? 0} suffix={`of ${stats?.recognized_countries ?? 249}`} /><Metric label="World explored" value={`${stats?.visited_percentage ?? 0}%`} /><Metric label="Timeline records" value={records} /></section><section className="panel continent-panel"><div className="section-heading"><div><p className="eyebrow">CONTINENTS</p><h2>Exploration by continent</h2></div></div><div className="continent-grid">{continents.map((item) => <div className="continent-counter" key={item.name}><strong>{item.visited}</strong><span>{item.name}</span><small>of {item.total} countries</small></div>)}</div></section><section className="map-card"><div className="section-heading"><h2>Your world map</h2></div><p className="muted map-help">Click any country to update its status.</p><WorldMap countries={countries} statuses={statuses} onSelect={onSelect} /></section></div> }

export default App
